package pbl6.ctsv.shcn.dotsinhhoat.reference;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import pbl6.ctsv.shcn.dotsinhhoat.reference.SemesterAudienceResolver.*;
import pbl6.ctsv.shcn.dotsinhhoat.exception.DotFailure;
import pbl6.ctsv.shcn.dotsinhhoat.dto.DotDtos.Query;
class SemesterAudienceResolverTest {
 Member student(long id,long classroom,String kind,String stop,String pause,String suspend){return new Member(id,"SV"+id,"Student "+id,classroom,"L"+classroom,"THUONG".equals(kind)?"Class "+classroom:"23RenLuyen_C1",1L,"2023","2023",kind,stop,pause,suspend);}
 @Test void periodGroupsComeFromStudentsOfThatPeriodNotAllSourceClasses(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0")),List.of());assertEquals(1,p.groups().khoaHoc().size());assertEquals(1,p.groups().khoaHoc().getFirst().soLop());assertEquals(1,p.members().size());}
 @Test void stoppedWithdrawnAndSuspendedAreExcludedFromRegularRecipients(){for(int f=0;f<3;f++){String[] flags={"0","0","0"};flags[f]="1";var m=student(1,10,"THUONG",flags[0],flags[1],flags[2]);assertTrue(SemesterAudienceResolver.resolve(List.of(m),List.of()).members().isEmpty());}}
 @Test void unknownFlagsAreNotSilentlyTreatedAsActive(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG",null,"0","0")),List.of());assertEquals("CAN_XAC_MINH",p.members().getFirst().verification());}
 @Test void explicitNegativeFlagsStillNeedRosterCoverageForRegularMembership(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","false","0")),List.of());assertEquals("CAN_XAC_MINH",p.members().getFirst().verification());}
 @Test void delayedRosterTakesPrecedenceOverOriginalClassAndDoesNotNeedAcademicRecord(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0")),List.of(student(1,30,"TRE_TIEN_DO",null,null,null)));assertEquals(1,p.members().size());assertEquals(30,p.members().getFirst().member().classId());assertTrue(p.groups().khoaHoc().isEmpty());assertEquals(1,p.groups().lopTreTienDo().getFirst().soSinhVien());}
 @Test void conflictingDelayedAssignmentsAreReportedNotChosenArbitrarily(){var e=assertThrows(DotFailure.class,()->SemesterAudienceResolver.resolve(List.of(),List.of(student(1,30,"TRE_TIEN_DO",null,null,null),student(1,31,"TRE_TIEN_DO",null,null,null))));assertEquals("SOURCE_MAPPING_INCOMPLETE",e.code());}
 @Test void duplicateAcademicRowsAreDeduplicatedAndPositiveFlagWins(){var a=student(1,10,"THUONG","0","0","0");assertEquals(1,SemesterAudienceResolver.resolve(List.of(a,a),List.of()).members().size());assertTrue(SemesterAudienceResolver.resolve(List.of(a,student(1,10,"THUONG","1","0","0")),List.of()).members().isEmpty());}
 @Test void missingCohortIsReportedWithoutGuessingFromClassName(){var m=new Member(1,"SV1","Student",10,"23DT1","23DT1",null,null,null,"THUONG","0","0","0");var p=SemesterAudienceResolver.resolve(List.of(m),List.of());assertEquals(1,p.groups().soLopChuaCoKhoa());assertTrue(p.groups().khoaHoc().isEmpty());assertEquals("CAN_XAC_MINH",p.members().getFirst().verification());}
 @Test void delayedRosterWithStopEvidenceIsUnverifiedAndStillAssignedToReceivingClass(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","1","0","0")),List.of(student(1,30,"TRE_TIEN_DO",null,null,null)));assertEquals("CAN_XAC_MINH",p.members().getFirst().verification());}

 @Test void twoStudentsInOneClassCountAsOneClassAndTwoPeople(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0"),student(2,10,"THUONG","0","0","0")),List.of());assertEquals(1,p.groups().khoaHoc().getFirst().soLop());assertEquals(2,p.members().size());}
 @Test void duplicateDelayedRowsDoNotInflateRecipientCount(){var m=student(1,30,"TRE_TIEN_DO",null,null,null);var p=SemesterAudienceResolver.resolve(List.of(),List.of(m,m));assertEquals(1,p.members().size());assertEquals(1,p.groups().lopTreTienDo().getFirst().soSinhVien());}
 @Test void delayedStatusIsVerifiedOnlyWhenSamePeriodAcademicEvidenceIsExplicitlyNegative(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0")),List.of(student(1,30,"TRE_TIEN_DO",null,null,null)));assertEquals("DU_CAN_CU_NGUON",p.members().getFirst().verification());}
 @Test void regularProfileInRenLuyenWithoutPeriodRosterDoesNotInventAnAssignment(){assertTrue(SemesterAudienceResolver.resolve(List.of(student(1,30,"TRE_TIEN_DO","0","0","0")),List.of()).members().isEmpty());}
 @Test void unrecognizedFlagIsUnverifiedNotAnExplicitNegative(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","unknown","0","0")),List.of());assertEquals("CAN_XAC_MINH",p.members().getFirst().verification());}
 @Test void missingStudentIdentityIsMappingErrorNotAnEmptySemester(){var m=student(0,10,"THUONG","0","0","0");assertEquals("SOURCE_MAPPING_INCOMPLETE",assertThrows(DotFailure.class,()->SemesterAudienceResolver.resolve(List.of(m),List.of())).code());}

 Query query(int page,int size,String q,boolean descending){return new Query(page,size,page*size,descending,q,null,null,null);}
 @Test void classesAreFilteredBySelectorAndCountsIncludeAllStudentsBeforePaging(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0"),student(2,10,"THUONG",null,null,null),student(3,11,"THUONG","0","0","0")),List.of());var out=SemesterAudienceResolver.classes(p,"KHOA_HOC","2023",query(0,1,"",false));assertEquals(2,out.totalElements());assertEquals(1,out.items().size());assertEquals(2,out.items().getFirst().soSinhVien());assertEquals(2,out.items().getFirst().soSinhVienCanXacMinh());}
 @Test void studentsFilterAndPageDoNotChangeSourceProjection(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0"),student(2,10,"THUONG",null,null,null)),List.of());var out=SemesterAudienceResolver.students(p,"L10",query(0,1,"Student",true));assertEquals(2,out.totalElements());assertEquals("SV2",out.items().getFirst().maSinhVien());assertFalse(out.items().getFirst().duCanCuNguon());assertEquals(2,p.members().size());}
 @Test void classOutsidePeriodIsRejectedInsteadOfReturningAnotherPeriodsStudents(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0")),List.of());assertThrows(DotFailure.class,()->SemesterAudienceResolver.students(p,"L11",query(0,25,"",false)));assertThrows(DotFailure.class,()->SemesterAudienceResolver.classes(p,"KHOA_HOC","2024",query(0,25,"",false)));}
 @Test void outOfRangePageReturnsEmptyWithCorrectTotal(){var p=SemesterAudienceResolver.resolve(List.of(student(1,10,"THUONG","0","0","0")),List.of());var out=SemesterAudienceResolver.students(p,"L10",query(3,25,"",false));assertTrue(out.items().isEmpty());assertEquals(1,out.totalElements());}
 @Test void renStudentsExposeReceivingClassAndExactPeriodEvidence(){var p=SemesterAudienceResolver.resolve(List.of(),List.of(student(1,30,"TRE_TIEN_DO",null,null,null)));var out=SemesterAudienceResolver.students(p,"L30",query(0,25,"",false));assertEquals("PHAN_LOP_REN_LUYEN_DUNG_KY",out.items().getFirst().canCu());assertEquals("LOP_NHAN_DUNG_KY",out.items().getFirst().canCuLop());assertEquals("CAN_XAC_MINH",out.items().getFirst().trangThaiXacMinh());}
}
